<?php require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/upgrade.php';$pdo=db();$adminRole=current_admin_role();
$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$lectures=[];$q=$pdo->query('SELECT l.*,c.name category_name,col.title collection_title FROM lectures l LEFT JOIN categories c ON c.id=l.category_id LEFT JOIN collections col ON col.id=l.collection_id');$lectureRows=$q->fetchAll();usort($lectureRows,function($left,$right){$leftDate=$left['session_date_gregorian']?:jalali_sort_key($left['session_date']);$rightDate=$right['session_date_gregorian']?:jalali_sort_key($right['session_date']);return strcmp($rightDate,$leftDate)?:((int)$right['id']<=>(int)$left['id']);});
foreach($lectureRows as $l){$l['id']=(int)$l['id'];$l['category_id']=$l['category_id']?(int)$l['category_id']:null;$l['collection_id']=$l['collection_id']?(int)$l['collection_id']:null;$l['session_number']=$l['session_number']?(int)$l['session_number']:null;$l['category']=$l['category_name']?:'';$l['collection_title']=$l['collection_title']?:'';unset($l['category_name']);$l['fishes']=[];$s=$pdo->prepare('SELECT * FROM fishes WHERE lecture_id=? ORDER BY timestamp_seconds,sort_order,id');$s->execute([$l['id']]);foreach($s as $f){$f['id']=(int)$f['id'];$f['lecture_id']=(int)$f['lecture_id'];$f['timestamp_seconds']=(int)$f['timestamp_seconds'];$f['tags']=get_tags($pdo,'fish',$f['id']);$l['fishes'][]=$f;}$p=$pdo->prepare('SELECT * FROM lecture_photos WHERE lecture_id=? ORDER BY sort_order,id');$p->execute([$l['id']]);$l['photos']=$p->fetchAll();$l['tags']=get_tags($pdo,'lecture',$l['id']);$lectures[]=$l;}
$articles=[];$q=$pdo->query('SELECT a.*,c.name category_name FROM articles a LEFT JOIN categories c ON c.id=a.category_id ORDER BY a.created_at DESC,a.id DESC');foreach($q as $a){$a['id']=(int)$a['id'];$a['category_id']=$a['category_id']?(int)$a['category_id']:null;$a['category']=$a['category_name']?:'';unset($a['category_name']);$a['tags']=get_tags($pdo,'article',$a['id']);$articles[]=$a;}
$ann=[];$announcementVisibility=$adminRole===null?' WHERE (a.start_date_gregorian IS NULL OR a.start_date_gregorian<=CURDATE()) AND (a.end_date_gregorian IS NULL OR a.end_date_gregorian>=CURDATE())':'';$q=$pdo->query('SELECT a.*,c.name category_name FROM announcements a LEFT JOIN categories c ON c.id=a.category_id'.$announcementVisibility.' ORDER BY a.created_at DESC,a.id DESC');foreach($q as $a){$a['id']=(int)$a['id'];$a['category']=$a['category_name']?:'';unset($a['category_name']);$a['tags']=get_tags($pdo,'announcement',$a['id']);$ann[]=$a;}
$collections=[];$q=$pdo->query('SELECT c.*,cat.name category FROM collections c LEFT JOIN categories cat ON cat.id=c.category_id ORDER BY COALESCE(c.start_date_gregorian,\'1000-01-01\') DESC,c.id DESC');foreach($q as $c){$c['id']=(int)$c['id'];$s=$pdo->prepare('SELECT lecture_id FROM collection_lectures WHERE collection_id=? ORDER BY lecture_id');$s->execute([$c['id']]);$c['lecture_ids']=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));$c['tags']=get_tags($pdo,'collection',$c['id']);$collections[]=$c;}
$tags=[];$q=$pdo->query('SELECT id,name,parent_id,definition FROM tags ORDER BY name');$parentRows=$pdo->query('SELECT tag_id,parent_id FROM tag_parents ORDER BY parent_id,tag_id')->fetchAll();$parentMap=[];foreach($parentRows as $parent)$parentMap[(int)$parent['tag_id']][]=(int)$parent['parent_id'];$countRows=$pdo->query("SELECT tag_id,SUM(content_type='lecture') lecture_count,SUM(content_type='fish') fish_count,SUM(content_type='article') article_count FROM content_tags WHERE content_type IN ('lecture','fish','article') GROUP BY tag_id")->fetchAll();$countMap=[];foreach($countRows as $count)$countMap[(int)$count['tag_id']]=$count;foreach($q as $t){$t['id']=(int)$t['id'];$t['parent_id']=$t['parent_id']?(int)$t['parent_id']:null;$t['parent_ids']=$parentMap[$t['id']]??[];$counts=$countMap[$t['id']]??[];$t['lecture_count']=(int)($counts['lecture_count']??0);$t['fish_count']=(int)($counts['fish_count']??0);$t['article_count']=(int)($counts['article_count']??0);$tags[]=$t;}
$photos=[];$q=$pdo->query("SELECT p.*,l.title lecture_title,l.session_date,l.hijri_date FROM lecture_photos p JOIN lectures l ON l.id=p.lecture_id ORDER BY p.created_at DESC,p.id DESC");foreach($q as $p){$photos[]=$p;}
foreach($ann as $a)if(!empty($a['poster_url']))$photos[]=['url'=>$a['poster_url'],'caption'=>$a['title'],'lecture_title'=>'اعلان','session_date'=>$a['event_date'],'hijri_date'=>'']; foreach($collections as $c)if(!empty($c['poster_url']))$photos[]=['url'=>$c['poster_url'],'caption'=>$c['title'],'lecture_title'=>'مجموعه','session_date'=>$c['start_jalali'],'hijri_date'=>''];
$settings=[];foreach($pdo->query('SELECT `key`,`value` FROM site_settings') as $s)$settings[$s['key']]=$s['value'];
$favorites=[];if(!empty($_SESSION['account_id'])){$favoriteQuery=$pdo->prepare('SELECT content_type,content_id FROM account_favorites WHERE account_id=?');$favoriteQuery->execute([(int)$_SESSION['account_id']]);$favorites=$favoriteQuery->fetchAll();}
$progress=[];if(!empty($_SESSION['account_id'])){$progressQuery=$pdo->prepare('SELECT lecture_id,position_seconds,duration_seconds,is_completed,updated_at FROM account_lecture_progress WHERE account_id=? ORDER BY updated_at DESC LIMIT 100');$progressQuery->execute([(int)$_SESSION['account_id']]);foreach($progressQuery as $row)$progress[(int)$row['lecture_id']]=['position_seconds'=>(int)$row['position_seconds'],'duration_seconds'=>(int)$row['duration_seconds'],'is_completed'=>(bool)$row['is_completed'],'updated_at'=>$row['updated_at']];}
json_out(['ok'=>true,'isAdmin'=>$adminRole!==null,'adminRole'=>$adminRole,'mustChangePassword'=>admin_must_change_password(),'csrfToken'=>csrf_token(),'isUser'=>!empty($_SESSION['account_id']),'username'=>$_SESSION['account_username']??null,'favorites'=>$favorites,'progress'=>$progress,'categories'=>$cats,'lectures'=>$lectures,'articles'=>$articles,'announcements'=>$ann,'collections'=>$collections,'tags'=>$tags,'gallery'=>$photos,'settings'=>$settings]);
